    internal static Geometry Get(string glyph, double size)
    {
        var key = glyph.Length == 1
            ? ((int)glyph[0]).ToString("X4", CultureInfo.InvariantCulture)
            : glyph;
        if (!Paths.TryGetValue(key, out var data))
            throw new ArgumentException("Unknown weather icon glyph.", nameof(glyph));
        if (!double.IsFinite(size) || size <= IconPadding * 2)
            throw new ArgumentOutOfRangeException(nameof(size));
        // A Geometry is owned by the first PathIcon that receives it. Parse a
        // fresh instance for each icon instead of sharing it across the card,
        // and scale the font-em coordinates into PathIcon's unscaled viewport.
        return Parse(data, (size - IconPadding * 2) / SourceExtent, IconPadding);
    }

    private static Geometry Parse(string data, double scale, double offset)
    {
        var geometry = new PathGeometry { FillRule = FillRule.Nonzero };
        PathFigure? figure = null;
        var index = data.StartsWith("F1", StringComparison.Ordinal) ? 2 : 0;
        while (true)
        {
            SkipSeparators(data, ref index);
            if (index >= data.Length) break;
            var command = data[index++];
            switch (command)
            {
                case 'M':
                    if (figure is not null) geometry.Figures.Add(figure);
                    figure = new PathFigure { StartPoint = ReadPoint(data, ref index, scale, offset), IsFilled = true };
                    break;
                case 'L':
                    RequireFigure(figure).Segments.Add(new LineSegment { Point = ReadPoint(data, ref index, scale, offset) });
                    break;
                case 'C':
                    RequireFigure(figure).Segments.Add(new BezierSegment
                    {
                        Point1 = ReadPoint(data, ref index, scale, offset),
                        Point2 = ReadPoint(data, ref index, scale, offset),
                        Point3 = ReadPoint(data, ref index, scale, offset)
                    });
                    break;
                case 'Z':
                    if (figure is not null)
                    {
                        figure.IsClosed = true;
                        geometry.Figures.Add(figure);
                        figure = null;
                    }
                    break;
                default:
                    throw new FormatException("Unsupported weather icon path command.");
            }
        }
        if (figure is not null) geometry.Figures.Add(figure);
        return geometry;
    }

    private static PathFigure RequireFigure(PathFigure? figure)
    {
        return figure ?? throw new FormatException("Weather icon path has a segment before its start point.");
    }

    private static Point ReadPoint(string data, ref int index, double scale, double offset)
    {
        var x = ReadNumber(data, ref index);
        var y = ReadNumber(data, ref index);
        return new Point(offset + x * scale, offset + y * scale);
    }

    private static double ReadNumber(string data, ref int index)
    {
        SkipSeparators(data, ref index);
        var start = index;
        if (index < data.Length && (data[index] == '-' || data[index] == '+')) index++;
        var sawDigit = false;
        while (index < data.Length && char.IsDigit(data[index])) { sawDigit = true; index++; }
        if (index < data.Length && data[index] == '.') { index++; while (index < data.Length && char.IsDigit(data[index])) { sawDigit = true; index++; } }
        if (!sawDigit) throw new FormatException("Weather icon path contains a malformed number.");
        if (index < data.Length && (data[index] == 'e' || data[index] == 'E'))
        {
            index++;
            if (index < data.Length && (data[index] == '-' || data[index] == '+')) index++;
            while (index < data.Length && char.IsDigit(data[index])) index++;
        }
        return double.Parse(data[start..index], NumberStyles.Float, CultureInfo.InvariantCulture);
    }

    private static void SkipSeparators(string data, ref int index)
    {
        while (index < data.Length && (char.IsWhiteSpace(data[index]) || data[index] == ',')) index++;
    }
